from collections import deque
R=C=16
seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  if grid[r][c]!=7 and (r,c) not in seen:
   q=deque([(r,c)]); seen.add((r,c)); cells=[]
   while q:
    x=q.popleft(); cells.append(x)
    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
     y=(x[0]+dr,x[1]+dc)
     if 0<=y[0]<R and 0<=y[1]<C and grid[y[0]][y[1]]!=7 and y not in seen:
      seen.add(y);q.append(y)
   vals=sorted(set(grid[x][y] for x,y in cells))
   box=(min(x for x,y in cells),max(x for x,y in cells),min(y for x,y in cells),max(y for x,y in cells))
   comps.append((box, len(cells), vals,cells))
[(b,n,vals) for b,n,vals,cells in comps]

out=[row[:] for row in grid]
selected=[]
for box,n,vals,cells in comps:
 if {2,4,6}.issubset(set(vals)) and box != (0,3,0,3):
  selected.append(box)
  for r,c in cells:
   out[r][c]=7
selected, '\n'.join(' '.join(map(str,row)) for row in out)
